create table hardware_private.workshop_catalog(id smallint primary key,definition jsonb not null);
create table hardware_private.workshop_attempts(room_id uuid not null references public.lab_rooms on delete cascade,round integer not null,user_id uuid not null references auth.users on delete cascade,lesson smallint not null references hardware_private.workshop_catalog,step integer not null default 0 check(step>=0),errors integer not null default 0 check(errors>=0),reward integer not null default 0 check(reward between 0 and 100),completed_at timestamptz,updated_at timestamptz not null default clock_timestamp(),primary key(room_id,round,user_id,lesson));
create table hardware_private.workshop_events(room_id uuid not null references public.lab_rooms on delete cascade,round integer not null,user_id uuid not null references auth.users on delete cascade,lesson smallint not null references hardware_private.workshop_catalog,step integer not null,choice integer not null,correct boolean not null,request uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(user_id,request));
alter table hardware_private.workshop_catalog enable row level security;
alter table hardware_private.workshop_attempts enable row level security;
alter table hardware_private.workshop_events enable row level security;
revoke all on hardware_private.workshop_catalog,hardware_private.workshop_attempts,hardware_private.workshop_events from public,anon,authenticated;
create index workshop_attempts_user_idx on hardware_private.workshop_attempts(user_id);
create index workshop_attempts_lesson_idx on hardware_private.workshop_attempts(lesson);
create index workshop_events_lesson_idx on hardware_private.workshop_events(lesson);
create index workshop_events_room_idx on hardware_private.workshop_events(room_id,round,created_at,user_id);
create function hardware_private.workshop_definition(p_lesson integer,p_round integer)
returns jsonb language sql stable set search_path='' as $$ select definition||case when definition ? 'variants' then (definition->'variants')->(greatest(0,p_round-1)%jsonb_array_length(definition->'variants')) else '{}'::jsonb end from hardware_private.workshop_catalog where id=p_lesson $$;
create function hardware_private.workshop_snapshot(p_room uuid,p_round integer,p_user uuid)
returns jsonb language sql stable set search_path='' as $$ select coalesce(jsonb_agg(to_jsonb(a) order by lesson),'[]'::jsonb) from hardware_private.workshop_attempts a where room_id=p_room and round=p_round and user_id=p_user $$;
create function hardware_private.workshop_action(p_room uuid,p_round integer,p_lesson integer,p_step integer,p_choice integer,p_request uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();r integer;c jsonb;s jsonb;a hardware_private.workshop_attempts;ev hardware_private.workshop_events;good boolean;paid integer:=0;message text;
begin
 if uid is null or p_request is null then raise exception 'Sessão expirada.';end if;
 select round into r from public.lab_rooms where id=p_room for share;if r is distinct from p_round then raise exception 'A rodada mudou. Reabra a atividade.';end if;
 perform 1 from public.lab_members where room_id=p_room and user_id=uid for update;if not found then raise exception 'Entre nesta turma.';end if;
 c:=hardware_private.workshop_definition(p_lesson,r);if c is null then raise exception 'Atividade inválida.';end if;
 insert into hardware_private.workshop_attempts(room_id,round,user_id,lesson) values(p_room,r,uid,p_lesson) on conflict do nothing;
 select * into a from hardware_private.workshop_attempts where room_id=p_room and round=r and user_id=uid and lesson=p_lesson for update;
 select * into ev from hardware_private.workshop_events where user_id=uid and request=p_request;
 if found then
  if ev.room_id<>p_room or ev.round<>r or ev.lesson<>p_lesson or ev.step is distinct from p_step or ev.choice is distinct from p_choice then raise exception 'Identificador já utilizado.';end if;
  good:=ev.correct;message:='Etapa já registrada. Nenhum pagamento duplicado.';
 elsif a.completed_at is not null then message:='Esta atividade já foi concluída nesta rodada.';
 else
  if p_step is null or p_step<>a.step then raise exception 'A etapa mudou. Reabra a atividade para continuar.';end if;
  s:=(c->'steps')->a.step;
  if p_choice is null or p_choice<0 or p_choice>=jsonb_array_length(s->'options') then raise exception 'Alternativa inválida.';end if;
  good:=p_choice=(s->>'answer')::integer;message:=case when good then 'Etapa concluída. ' else 'Vamos rever. ' end||(s->>'feedback');
  insert into hardware_private.workshop_events(room_id,round,user_id,lesson,step,choice,correct,request) values(p_room,r,uid,p_lesson,a.step,p_choice,good,p_request);
  if good then a.step:=a.step+1;else a.errors:=a.errors+1;end if;
  if a.step=jsonb_array_length(c->'steps') then paid:=greatest(20,(c->>'reward')::integer-a.errors*5);a.completed_at:=clock_timestamp();a.reward:=paid;end if;
  update hardware_private.workshop_attempts set step=a.step,errors=a.errors,reward=a.reward,completed_at=a.completed_at,updated_at=clock_timestamp() where room_id=p_room and round=r and user_id=uid and lesson=p_lesson;
 end if;
 return jsonb_build_object('round',r,'progress',to_jsonb(a),'correct',good,'completed',paid>0,'reward',paid,'feedback',message);
end $$;
create function public.lab_workshop_action(p_room uuid,p_round integer,p_lesson integer,p_step integer,p_choice integer,p_request uuid)
returns jsonb language sql security invoker set search_path='' as $$ select hardware_private.workshop_action(p_room,p_round,p_lesson,p_step,p_choice,p_request) $$;
revoke all on function hardware_private.workshop_action(uuid,integer,integer,integer,integer,uuid),public.lab_workshop_action(uuid,integer,integer,integer,integer,uuid) from public,anon;
grant execute on function hardware_private.workshop_action(uuid,integer,integer,integer,integer,uuid),public.lab_workshop_action(uuid,integer,integer,integer,integer,uuid) to authenticated;
create or replace function hardware_private.extra_wallet(p_room uuid,p_round integer,p_user uuid)
returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('bonus',coalesce((select sum(reward) from hardware_private.customer_jobs where room_id=p_room and round=p_round and completed_user=p_user),0)+w.reward,'bonus_solved',(select count(*) from hardware_private.customer_jobs where room_id=p_room and round=p_round and completed_user=p_user),'workshop_bonus',w.reward,'workshop_solved',w.solved,'expenses',coalesce((select sum(cost) from hardware_private.floor_incidents where room_id=p_room and round=p_round and user_id=p_user),0)+coalesce((select sum(cost) from hardware_private.celebration_purchases where room_id=p_room and round=p_round and user_id=p_user),0)) from (select coalesce(sum(reward),0) as reward,count(*) filter(where completed_at is not null) as solved from hardware_private.workshop_attempts where room_id=p_room and round=p_round and user_id=p_user) w
$$;
create function hardware_private.workshop_report(p_room uuid,p_round integer,p_user uuid,p_from timestamptz,p_until timestamptz)
returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;r integer;
begin
 if auth.uid() is null or not exists(select 1 from hardware_private.admin_sessions where user_id=auth.uid() and expires_at>now()) then raise exception 'Acesso exclusivo do professor.';end if;
 select coalesce(p_round,round) into r from public.lab_rooms where id=p_room;if r is null then raise exception 'Turma não encontrada.';end if;
 if p_from is null or p_until is null or p_from>=p_until then raise exception 'Período inválido.';end if;
 select jsonb_build_object('attempts',hardware_private.workshop_snapshot(p_room,r,p_user),'events',coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at) from (select lesson,step,choice,correct,created_at from hardware_private.workshop_events where room_id=p_room and round=r and user_id=p_user and created_at>=p_from and created_at<p_until order by created_at desc limit 2000) e),'[]'::jsonb)) into result;return result;
end $$;
create function public.lab_workshop_report(p_room uuid,p_round integer,p_user uuid,p_from timestamptz default '-infinity',p_until timestamptz default 'infinity')
returns jsonb language sql security invoker set search_path='' as $$ select hardware_private.workshop_report(p_room,p_round,p_user,p_from,p_until) $$;
revoke all on function hardware_private.workshop_report(uuid,integer,uuid,timestamptz,timestamptz),public.lab_workshop_report(uuid,integer,uuid,timestamptz,timestamptz) from public,anon;
grant execute on function hardware_private.workshop_report(uuid,integer,uuid,timestamptz,timestamptz),public.lab_workshop_report(uuid,integer,uuid,timestamptz,timestamptz) to authenticated;
create function hardware_private.learning_map(p_room uuid,p_round integer,p_from timestamptz,p_until timestamptz)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r integer;result jsonb;
begin
 if auth.uid() is null or not exists(select 1 from hardware_private.admin_sessions where user_id=auth.uid() and expires_at>now()) then raise exception 'Acesso exclusivo do professor.';end if;
 select coalesce(p_round,round) into r from public.lab_rooms where id=p_room;if r is null then raise exception 'Turma não encontrada.';end if;
 if p_from is null or p_until is null or p_from>=p_until then raise exception 'Período inválido.';end if;
 with events as (
 select 'pc' as kind,pc as item,user_id,correct,kind in ('diagnosis','repair','challenge') as assessed from hardware_private.response_events where room_id=p_room and round=r and created_at>=p_from and created_at<p_until
 union all select 'client',customer,user_id,correct,kind in ('diagnosis','repair') from hardware_private.customer_events where room_id=p_room and round=r and created_at>=p_from and created_at<p_until
 union all select 'workshop',lesson,user_id,correct,true from hardware_private.workshop_events where room_id=p_room and round=r and created_at>=p_from and created_at<p_until
 ), totals as (select kind,item,count(distinct user_id) as students,count(*) filter(where assessed) as answers,count(*) filter(where assessed and correct=false) as errors from events group by kind,item), completions as (
 select 'pc' as kind,pc as item,count(*) as solved from public.lab_completions where room_id=p_room and round=r and completed_at>=p_from and completed_at<p_until group by pc
 union all select 'client',customer,count(*) from hardware_private.customer_jobs where room_id=p_room and round=r and completed_at>=p_from and completed_at<p_until group by customer
 union all select 'workshop',lesson,count(*) from hardware_private.workshop_attempts where room_id=p_room and round=r and completed_at>=p_from and completed_at<p_until group by lesson
 ), items as (select 'pc' as kind,generate_series(0,79) as item union all select 'client',id from hardware_private.customer_catalog union all select 'workshop',id from hardware_private.workshop_catalog)
 select coalesce(jsonb_agg(jsonb_build_object('kind',i.kind,'item',i.item,'students',coalesce(t.students,0),'answers',coalesce(t.answers,0),'errors',coalesce(t.errors,0),'solved',coalesce(c.solved,0)) order by i.kind,i.item),'[]'::jsonb) into result from items i left join totals t on t.kind=i.kind and t.item=i.item left join completions c on c.kind=i.kind and c.item=i.item;
 return jsonb_build_object('round',r,'items',result);
end $$;
create function public.lab_learning_map(p_room uuid,p_round integer default null,p_from timestamptz default '-infinity',p_until timestamptz default 'infinity')
returns jsonb language sql security invoker set search_path='' as $$ select hardware_private.learning_map(p_room,p_round,p_from,p_until) $$;
revoke all on function hardware_private.learning_map(uuid,integer,timestamptz,timestamptz),public.lab_learning_map(uuid,integer,timestamptz,timestamptz) from public,anon;
grant execute on function hardware_private.learning_map(uuid,integer,timestamptz,timestamptz),public.lab_learning_map(uuid,integer,timestamptz,timestamptz) to authenticated;
revoke all on function hardware_private.workshop_definition(integer,integer),hardware_private.workshop_snapshot(uuid,integer,uuid) from public,anon,authenticated;

do $migration$
declare definition text;
begin
 select pg_get_functiondef('hardware_private.snapshot(uuid,integer)'::regprocedure) into definition;
 if position('if not teacher and r.competition_mode' in definition)=0 then raise exception 'Unexpected snapshot';end if;
 definition:=replace(definition,'if not teacher and r.competition_mode',$patch$
 with earnings as (
 select user_id,score,1 as solved,0 as extra,0 as practice from public.lab_completions where room_id=p_room and round=target_round
 union all select completed_user,reward,0,1,0 from hardware_private.customer_jobs where room_id=p_room and round=target_round and completed_user is not null
 union all select user_id,reward,0,0,1 from hardware_private.workshop_attempts where room_id=p_room and round=target_round and completed_at is not null
 ), totals as (select user_id,sum(score)::integer as earned,sum(solved)::integer as solved,sum(extra)::integer as extra_solved,sum(practice)::integer as workshop_solved from earnings group by user_id)
 select coalesce(jsonb_agg(jsonb_build_object('user_id',t.user_id,'name',m.nickname,'earned',t.earned,'score',greatest(0,t.earned-(w.value->>'expenses')::integer),'expenses',(w.value->>'expenses')::integer,'solved',t.solved,'extra_solved',t.extra_solved,'workshop_solved',t.workshop_solved) order by greatest(0,t.earned-(w.value->>'expenses')::integer) desc,m.nickname,t.user_id),'[]'::jsonb) into scores from totals t join public.lab_members m on m.room_id=p_room and m.user_id=t.user_id cross join lateral (select hardware_private.extra_wallet(p_room,target_round,t.user_id) as value) w;
 if not teacher and r.competition_mode$patch$);
 definition:=replace(definition,'''customers'',hardware_private.customer_snapshot','''workshops'',hardware_private.workshop_snapshot(p_room,target_round,uid),''customers'',hardware_private.customer_snapshot');execute definition;
 select pg_get_functiondef('hardware_private.enrich_customer_students(uuid,integer,jsonb,timestamptz,timestamptz)'::regprocedure) into definition;
 definition:=replace(definition,'''extra_solved'',','''workshop_solved'',coalesce(w.solved,0),''workshop_bonus'',coalesce(w.bonus,0),''extra_solved'',');
