end $migration$;

insert into hardware_private.workshop_catalog(id,definition) values
(0,'{"id":0,"title":"Conheça as peças","tag":"PRIMEIROS PASSOS","reward":40,"description":"Reconheça seis componentes pelas ilustrações e pela função.","steps":[{"kind":"identify","picture":"cpu","title":"Que peça é esta?","options":["Memória RAM","Processador (CPU)","Chipset","SSD SATA de 2,5 polegadas","Placa-mãe","Fonte de alimentação"],"answer":1,"feedback":"A CPU executa instruções. Neste desenho, ela é o componente removível instalado no soquete."},{"kind":"identify","picture":"ram","title":"Identifique o módulo","options":["Memória RAM","Processador (CPU)","Chipset","SSD SATA de 2,5 polegadas","Placa-mãe","Fonte de alimentação"],"answer":0,"feedback":"A RAM é a memória de trabalho volátil. Observe os chips, os contatos e o entalhe."},{"kind":"identify","picture":"chipset","title":"Quem é este circuito na placa?","options":["Memória RAM","Processador (CPU)","Chipset","SSD SATA de 2,5 polegadas","Placa-mãe","Fonte de alimentação"],"answer":2,"feedback":"O chipset auxilia a comunicação com periféricos e interfaces. Não é a CPU; sua função e localização variam conforme a plataforma."},{"kind":"identify","picture":"ssd","title":"Onde ficam os arquivos?","options":["Memória RAM","Processador (CPU)","Chipset","SSD SATA de 2,5 polegadas","Placa-mãe","Fonte de alimentação"],"answer":3,"feedback":"Este SSD SATA de 2,5 polegadas conserva dados sem energia. Existem também SSDs em outros formatos, como M.2."},{"kind":"identify","picture":"board","title":"Identifique a placa que reúne o conjunto","options":["Memória RAM","Processador (CPU)","Chipset","SSD SATA de 2,5 polegadas","Placa-mãe","Fonte de alimentação"],"answer":4,"feedback":"A placa-mãe conecta os componentes e oferece soquetes, slots e interfaces."},{"kind":"identify","picture":"psu","title":"Quem fornece a alimentação?","options":["Memória RAM","Processador (CPU)","Chipset","SSD SATA de 2,5 polegadas","Placa-mãe","Fonte de alimentação"],"answer":5,"feedback":"A fonte converte a alimentação da rede nas tensões utilizadas pelo computador. Sua carcaça não deve ser aberta."}]}'::jsonb),
(1,'{"id":1,"title":"Monte o computador","tag":"ARRASTE E ENCAIXE","reward":80,"description":"CPU, RAM, armazenamento e alimentação em uma placa didática.","steps":[{"kind":"choice","title":"Prepare a bancada","text":"Antes de tocar em componentes internos, qual é a preparação correta?","options":["Desligar, desconectar a alimentação e adotar cuidados contra descarga eletrostática","Deixar ligado para observar melhor","Abrir a carcaça da fonte"],"answer":0,"feedback":"Desligue e desconecte antes de manusear. Segure as placas pelas bordas e siga o manual. Nunca abra a fonte."},{"kind":"place","part":"cpu","title":"Leve a CPU ao soquete compatível","options":["Soquete da CPU","Slot DIMM","Porta SATA","Slot PCIe"],"answer":0,"feedback":"Alinhe as marcações conforme o manual. Não force o processador."},{"kind":"place","part":"ram","title":"Encaixe o módulo de RAM","options":["Soquete da CPU","Slot DIMM compatível","Porta SATA","Conector CPU_FAN"],"answer":1,"feedback":"Confira geração, entalhe e slot recomendado no manual. As travas devem indicar o assentamento correto."},{"kind":"place","part":"sata","title":"Conecte os dados do SSD SATA","options":["CPU_FAN","Porta SATA de dados","Slot DIMM","Conector EPS"],"answer":1,"feedback":"SATA de dados e alimentação são conexões diferentes. Um SSD SATA precisa das duas."},{"kind":"place","part":"atx","title":"Conecte a alimentação principal","options":["Header USB","Slot PCIe","ATX de 24 pinos","Porta SATA"],"answer":2,"feedback":"O ATX principal alimenta a placa-mãe. A CPU também pode exigir alimentação EPS específica; não misture cabos modulares de fontes diferentes."}]}'::jsonb),
(2,'{"id":2,"title":"Cuide da memória RAM","tag":"LIMPEZA SIMULADA","reward":60,"description":"Cuidados contra estática, limpeza suave, secagem e encaixe.","steps":[{"kind":"choice","title":"Prepare a bancada","text":"Antes de tocar em componentes internos, qual é a preparação correta?","options":["Desligar, desconectar a alimentação e adotar cuidados contra descarga eletrostática","Deixar ligado para observar melhor","Abrir a carcaça da fonte"],"answer":0,"feedback":"Desligue e desconecte antes de manusear. Segure as placas pelas bordas e siga o manual. Nunca abra a fonte."},{"kind":"choice","title":"Escolha o material adequado","text":"Para sujeira persistente nos contatos, qual material é apropriado, seguindo o fabricante?","options":["Borracha abrasiva e força","Aplicador levemente umedecido com álcool isopropílico de alta pureza","Água em abundância"],"answer":1,"feedback":"Use produto apropriado com moderação e toque suave. Abrasão pode danificar o acabamento dos contatos."},{"kind":"wipe","picture":"ram","title":"Limpe suavemente os contatos","text":"Passe o aplicador nas quatro áreas marcadas. No celular, arraste ou toque em cada área. A peça está fora do slot e sem alimentação.","options":["Limpeza suave concluída"],"answer":0,"feedback":"Remova somente a sujeira. Segure pelas bordas e evite tocar nos contatos."},{"kind":"choice","title":"Antes de reinstalar","text":"A limpeza já terminou. O que ainda precisa acontecer?","options":["Ligar para acelerar a secagem","Reinstalar ainda úmida","Aguardar a secagem completa conforme o produto e o fabricante"],"answer":2,"feedback":"A secagem deste jogo é simbólica: não representa um tempo seguro para uma peça real. Só reinstale quando estiver completamente seca."},{"kind":"place","part":"ram","title":"Reinstale sem forçar o entalhe","options":["Porta SATA","Slot DIMM compatível","Slot PCIe","CPU_FAN"],"answer":1,"feedback":"Confirme o encaixe e depois teste a memória. Limpeza não conserta chips defeituosos; isole módulo e slot antes de concluir o diagnóstico."}]}'::jsonb),
(3,'{"id":3,"title":"Teste virtual da fonte","tag":"SIMULAÇÃO ATX","reward":80,"description":"Identifique PS_ON e COM e interprete as limitações do teste.","steps":[{"kind":"choice","title":"Prepare a bancada","text":"Esta é uma fonte virtual isolada do computador. Antes de colocar um jumper, ela deve estar desligada e desconectada. Qual preparação você escolhe?","options":["Desligar, desconectar a alimentação e adotar cuidados contra descarga eletrostática","Deixar ligado para observar melhor","Abrir a carcaça da fonte"],"answer":0,"feedback":"Desligue e desconecte antes de manusear. Segure as placas pelas bordas e siga o manual. Nunca abra a fonte."},{"kind":"pins","picture":"psu","title":"Posicione o jumper virtual","text":"Conector ATX de 24 pinos, lado de encaixe voltado para você, trava acima. Selecione PS_ON (16, verde) e COM (preto). Os números e os sinais identificam os pinos; não dependa apenas das cores.","options":["Jumper PS_ON–COM","Ligação incorreta"],"answer":0,"feedback":"O jumper de partida une PS_ON a COM. Não conecte saídas de tensão entre si. Em fontes reais, siga o pinout do fabricante; conectores proprietários e o lado modular não seguem necessariamente este desenho."},{"kind":"choice","title":"Acione somente a simulação","text":"O jumper virtual correto está colocado. A bancada mantém a fonte fechada e os demais componentes desconectados.","options":["Ligar o teste virtual","Abrir a fonte para observar os capacitores"],"answer":0,"feedback":"Esta atividade ocorre somente na tela. Em equipamento real, o procedimento cabe ao professor ou técnico habilitado, seguindo o fabricante e usando equipamento apropriado."},{"kind":"inspect","picture":"tester","title":"Leia o testador virtual","text":"Na fonte didática: +12 V = 12,1 V; +5 V = 5,0 V; +3,3 V = 3,3 V. A ventoinha gira brevemente e para no modo zero RPM.","options":["Registrar a medição simulada"],"answer":0,"feedback":"Algumas fontes param a ventoinha em baixa carga. A rotação, isoladamente, não determina a saúde da fonte."},{"kind":"choice","title":"O teste comprova tudo?","text":"A fonte virtual partiu e exibiu tensões. Ela está aprovada em qualquer carga?","options":["Sim, a ventoinha é prova suficiente","Não: ainda são necessários testes apropriados de tensões e comportamento sob carga"],"answer":1,"feedback":"Um jumper verifica a partida, sem certificar estabilidade, ondulação ou capacidade sob carga. Não abra a fonte, mesmo fora da tomada."}]}'::jsonb),
(4,'{"id":4,"title":"Escute o POST","tag":"BIPES COM SOM","reward":60,"description":"Ouça padrões e consulte o manual de uma placa didática.","steps":[{"kind":"audio","pattern":[0.16,0.16,0.16],"title":"Ouça o primeiro padrão","options":["Falha na RAM","Falha de vídeo","Verificar CPU_FAN"],"answer":0,"feedback":"Neste manual fictício MH-EDU v1, três bipes curtos indicam investigação da RAM. Em equipamentos reais, os códigos dependem do fabricante e do modelo."},{"kind":"audio","pattern":[0.55,0.16,0.16],"title":"Um padrão diferente","options":["Falha na RAM","Falha de vídeo","Verificar CPU_FAN"],"answer":1,"feedback":"No MH-EDU v1, um longo e dois curtos apontam para o vídeo. Consulte sempre a documentação do equipamento real."},{"kind":"audio","pattern":[0.16,0.16,0.16,0.16,0.16,0.16],"title":"Compare com o manual","options":["Falha na RAM","Falha de vídeo","Verificar CPU_FAN"],"answer":2,"feedback":"Seis curtos correspondem a CPU_FAN somente neste manual didático. Bipes orientam testes; não substituem a investigação."}]}'::jsonb),
(5,'{"id":5,"title":"Encontre o cabo solto","tag":"INSPEÇÃO VISUAL","reward":60,"description":"Observe o interior e recoloque o cabo de dados SATA.","steps":[{"kind":"choice","title":"Prepare a bancada","text":"Antes de tocar em componentes internos, qual é a preparação correta?","options":["Desligar, desconectar a alimentação e adotar cuidados contra descarga eletrostática","Deixar ligado para observar melhor","Abrir a carcaça da fonte"],"answer":0,"feedback":"Desligue e desconecte antes de manusear. Segure as placas pelas bordas e siga o manual. Nunca abra a fonte."},{"kind":"hotspot","picture":"inside","title":"Onde está o problema visível?","text":"Observe a ilustração: o disco secundário não aparece. Toque na área em que o cabo de dados não está assentado.","options":["Cabo de dados SATA","Alimentação do SSD","Ventoinha da CPU","Módulo de RAM"],"answer":0,"feedback":"O cabo estreito de dados está fora da porta SATA da placa-mãe. A alimentação do SSD permanece conectada."},{"kind":"place","part":"sata","title":"Reconecte os dados do SSD","options":["Porta SATA de dados","Slot DIMM","Conector CPU_FAN","ATX principal"],"answer":0,"feedback":"Com a alimentação desconectada, alinhe o conector em L sem forçar. Depois confirme a detecção no firmware e o acesso aos dados; não formate a unidade."}]}'::jsonb),
(6,'{"id":6,"title":"Cabos no lugar certo","tag":"CONECTORES","reward":80,"description":"Diferencie CPU_FAN, EPS e conexões parecidas.","steps":[{"kind":"choice","title":"Prepare a bancada","text":"Antes de tocar em componentes internos, qual é a preparação correta?","options":["Desligar, desconectar a alimentação e adotar cuidados contra descarga eletrostática","Deixar ligado para observar melhor","Abrir a carcaça da fonte"],"answer":0,"feedback":"Desligue e desconecte antes de manusear. Segure as placas pelas bordas e siga o manual. Nunca abra a fonte."},{"kind":"place","part":"fan","title":"Ligue a ventoinha do dissipador","options":["SATA","CPU_FAN, conforme o manual","USB interno","ATX principal"],"answer":1,"feedback":"CPU_FAN permite alimentar e monitorar a ventoinha do dissipador. Não confunda com headers de função diferente."},{"kind":"place","part":"eps","title":"Leve o cabo CPU/EPS ao conector correto","options":["PCIe de vídeo","SATA de dados","CPU/EPS compatível","USB interno"],"answer":2,"feedback":"EPS/CPU e PCIe/GPU têm funções e pinagens diferentes. Confira as inscrições e o manual; nunca force o encaixe."}]}'::jsonb),
(7,'{"id":7,"title":"Diagnóstico surpresa","tag":"MUDA POR RODADA","reward":100,"description":"O mesmo sintoma, causas diferentes. Investigue novamente a cada rodada.","variants":[{"title":"Sem imagem: investigue a memória","steps":[{"kind":"inspect","picture":"board","title":"O sintoma","text":"O computador liga, mas não mostra imagem. Não substitua peças apenas pelo sintoma.","options":["Consultar a primeira evidência"],"answer":0,"feedback":"A entrada selecionada e o cabo do monitor foram conferidos e funcionam."},{"kind":"inspect","picture":"ram","title":"A segunda evidência","text":"Com o equipamento desconectado, uma ponta da RAM aparece levantada, com a trava aberta. O módulo funciona em uma bancada de teste.","options":["Registrar a evidência"],"answer":0,"feedback":"O teste isolado e a inspeção apontam para o encaixe, não para um módulo queimado."},{"kind":"choice","title":"Qual causa reúne as evidências?","text":"Use os dois resultados, não apenas a tela preta.","options":["RAM mal assentada","Entrada errada no monitor","GPU necessariamente queimada"],"answer":0,"feedback":"O módulo aprovado está mal assentado. A mesma tela preta pode ter outras causas em outra rodada."},{"kind":"place","part":"ram","title":"Corrija o encaixe nesta simulação","options":["Porta SATA","Slot DIMM compatível","CPU_FAN","Slot PCIe"],"answer":1,"feedback":"Com o PC desconectado, reinstale conforme o manual. O POST e o teste de memória confirmam a solução nesta bancada."}]},{"title":"Sem imagem: investigue o monitor","steps":[{"kind":"inspect","picture":"board","title":"O mesmo sintoma","text":"O computador liga, mas não mostra imagem. O POST termina e não há indicador de falha na placa.","options":["Consultar a primeira evidência"],"answer":0,"feedback":"RAM e inicialização passaram nos testes. Não há evidência de módulo defeituoso."},{"kind":"inspect","picture":"monitor","title":"Observe a entrada","text":"O cabo está no HDMI 1, mas o monitor está selecionado em DisplayPort. Selecionar HDMI 1 exibe a imagem.","options":["Registrar a evidência"],"answer":0,"feedback":"A comparação identifica a seleção da entrada do monitor."},{"kind":"choice","title":"Qual é o diagnóstico desta rodada?","text":"A tela preta tem uma causa diferente da rodada anterior.","options":["RAM mal assentada","Entrada incorreta no monitor","SSD defeituoso"],"answer":1,"feedback":"A entrada selecionada não correspondia à conexão física."},{"kind":"choice","title":"Aplique a solução","text":"Preserve o hardware que passou nos testes.","options":["Trocar a RAM","Formatar o SSD","Selecionar HDMI 1 e confirmar a imagem"],"answer":2,"feedback":"A imagem voltou ao selecionar a entrada correta, sem substituir peças."}]},{"title":"Sem imagem: investigue a alimentação da CPU","steps":[{"kind":"inspect","picture":"board","title":"Mais um caso sem imagem","text":"As ventoinhas giram, mas o POST não termina. Monitor e cabo funcionam em outro computador.","options":["Consultar a primeira evidência"],"answer":0,"feedback":"Girar a ventoinha não garante que todas as alimentações estejam conectadas."},{"kind":"inspect","picture":"eps","title":"Inspeção com o PC desconectado","text":"O ATX principal está conectado. O cabo CPU/EPS está fora do conector indicado no manual. A fonte foi aprovada em teste apropriado.","options":["Registrar a evidência"],"answer":0,"feedback":"A CPU está sem a alimentação auxiliar exigida por esta placa."},{"kind":"choice","title":"Qual causa explica os testes?","text":"Considere a alimentação que falta.","options":["Monitor avariado","RAM necessariamente defeituosa","CPU sem alimentação auxiliar"],"answer":2,"feedback":"É necessário conferir todos os conectores exigidos pela placa."},{"kind":"place","part":"eps","title":"Conecte o cabo correto","options":["SATA","CPU/EPS compatível","Header USB","Conector PCIe de vídeo"],"answer":1,"feedback":"O cabo CPU/EPS compatível restabeleceu o POST. Não use PCIe de vídeo nem cabos modulares de outra fonte."}]}]}'::jsonb);

do $questions$
declare definition text;
begin
 select pg_get_functiondef('hardware_private.customer_action(uuid,integer,integer,text,integer,uuid,double precision,double precision)'::regprocedure) into definition;
 if position('if p_kind=''renew'' then null;' in definition)=0 then raise exception 'Unexpected customer action';end if;
 definition:=replace(definition,'if p_kind=''renew'' then null;','if p_kind=''renew'' then null; elsif p_kind=''question'' and p_choice between 0 and 2 then null;');
 execute definition;
end $questions$;
